const code = $input.item.json.code || $input.item.json.body?.code;
const language = $input.item.json.language || 'javascript';
const repoUrl = $input.item.json.repo_url;
const pullRequestNumber = $input.item.json.pr_number;

if (!code && !repoUrl) {
  throw new Error('No code or repository URL provided');
}

return {
  json: {
    request_id: `review_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString(),
    code: code,
    language: language,
    repo_url: repoUrl,
    pr_number: pullRequestNumber,
    code_length: code?.length || 0,
    analysis_types: ['quality', 'security', 'performance', 'best_practices']
  }
};

