parameters.functionCode:
const items = $input.all();
const baseData = items.find(item => item.json.request_id)?.json;

// Extract GPT-4 code quality results
const gptQualityResult = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.overall_score !== undefined && parsed.issues;
    }
  } catch (e) {}
  return false;
});
const qualityReview = gptQualityResult ? JSON.parse(gptQualityResult.json.choices[0].message.content) : null;

// Extract GPT-4 security results
const gptSecurityResult = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.security_score !== undefined && parsed.vulnerabilities;
    }
  } catch (e) {}
  return false;
});
const securityScan = gptSecurityResult ? JSON.parse(gptSecurityResult.json.choices[0].message.content) : null;

// Calculate combined score
const combinedScore = qualityReview && securityScan ?
  Math.round((qualityReview.overall_score * 0.6 + securityScan.security_score * 0.4)) : 
  (qualityReview?.overall_score || securityScan?.security_score || 0);

// Categorize all issues by severity
const allIssues = [
  ...(qualityReview?.issues || []).map(i => ({...i, category: 'quality'})),
  ...(securityScan?.vulnerabilities || []).map(v => ({...v, category: 'security'}))
];

const issuesBySeverity = {
  critical: allIssues.filter(i => i.severity === 'critical').length,
  high: allIssues.filter(i => i.severity === 'high').length,
  medium: allIssues.filter(i => i.severity === 'medium').length,
  low: allIssues.filter(i => i.severity === 'low').length
};

// Generate recommendation
let recommendation = 'APPROVED';
if (issuesBySeverity.critical > 0) {
  recommendation = 'REJECTED - Critical issues must be fixed';
} else if (issuesBySeverity.high > 2) {
  recommendation = 'REQUEST CHANGES - Multiple high-severity issues';
} else if (combinedScore < 60) {
  recommendation = 'REQUEST CHANGES - Code quality below threshold';
} else if (issuesBySeverity.high > 0 || issuesBySeverity.medium > 5) {
  recommendation = 'COMMENT - Address issues before merge';
}

const result = {
  request_id: baseData?.request_id,
  timestamp: baseData?.timestamp,
  code_info: {
    language: baseData?.language,
    length: baseData?.code_length,
    repo_url: baseData?.repo_url,
    pr_number: baseData?.pr_number
  },
  review_summary: {
    combined_score: combinedScore,
    quality_score: qualityReview?.overall_score || null,
    security_score: securityScan?.security_score || null,
    recommendation: recommendation,
    issues_count: allIssues.length,
    issues_by_severity: issuesBySeverity
  },
  quality_review: {
    score: qualityReview?.overall_score || null,
    summary: qualityReview?.summary || '',
    issues: (qualityReview?.issues || []).slice(0, 20)
  },
  security_scan: {
    score: securityScan?.security_score || null,
    vulnerabilities: (securityScan?.vulnerabilities || []).slice(0, 20),
    compliance_issues: securityScan?.compliance_issues || []
  },
  top_issues: allIssues
    .sort((a, b) => {
      const severityOrder = {critical: 0, high: 1, medium: 2, low: 3};
      return severityOrder[a.severity] - severityOrder[b.severity];
    })
    .slice(0, 10),
  metadata: {
    reviewers_used: ['gpt4_quality', 'gpt4_security'],
    processing_time_ms: Date.now() - new Date(baseData?.timestamp).getTime()
  }
};

return { json: result };

